@dataclass(kw_only=True, slots=True)
class LineCreate(_Model):
    """Input of `cad.line.create` v1: one straight line from `a` to `b` on a
    named layer, written as one undo step. The line tool calls it once per
    segment of its chain, so each segment stays its own object and its own
    undo step (docs/adr/0027). Everything the command depends on is here
    (TODOS.md CMD-07): the tool fills `layerId` from the active layer and
    `color` from the current colour; the command reads neither.

    Refusals (`CommandError.code`), checked in this order: `not_finite` (`a`,
    then `b`, x before y), `invalid_line_weight` (not from 0 to 100 mm), `invalid_revision`, `revision_conflict` (status
    `conflict`), `layer_not_found`, `not_a_layer`, `layer_locked`; on the
    desktop also `slots_exhausted`. Warning: `layer_hidden` (it is written
    all the same). A line whose ends coincide is not refused: geometric
    validity is not checked, as for `cad.polygon.create`.
    Attributes:
        layer_id: The layer it goes on: a layer's id (`LayerNode.id`), not a group's.
        a: Where it starts: x east (Y), y north (X), in the project's units (m), float64.
        b: Where it ends.
        attrs: GIS attributes, text in v1. Absent: none.
        color: Colour override (`EntityBase.color`). Absent: the layer's colour (katmana göre).
        expected_revision: The document revision the input was prepared against, as decimal text
            (from a plan, or the document). When given and the document is no
            longer at it, nothing is written and the answer is `conflict`.
        label: The text shown beside it (`EntityBase.label`). Absent: none.
        line_weight: Its own line weight, paper mm (`EntityBase.line_weight`, 0 the
            thinnest, at most 100; docs/adr/0139): what the tools give a new
            object from the current weight. Absent: the layer's (katmana göre).
        symbol: Its own symbol, a library item's id (`EntityBase.symbol`), drawn
            instead of its layer's style: an object template's (docs/adr/0176).
            The id is not looked up: the libraries are the host's. Absent: the
            layer's style.
    """
    layer_id: str
    a: Vec2
    b: Vec2
    attrs: dict[str, str] | None | Unset = UNSET
    color: str | None | Unset = UNSET
    expected_revision: str | None | Unset = UNSET
    label: str | None | Unset = UNSET
    line_weight: float | None | Unset = UNSET
    symbol: str | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["layerId"] = self.layer_id
        out["a"] = _vec2_out(self.a)
        out["b"] = _vec2_out(self.b)
        if self.attrs is not UNSET:
            out["attrs"] = None if self.attrs is None else dict(self.attrs)
        if self.color is not UNSET:
            out["color"] = self.color
        if self.expected_revision is not UNSET:
            out["expectedRevision"] = self.expected_revision
        if self.label is not UNSET:
            out["label"] = self.label
        if self.line_weight is not UNSET:
            out["lineWeight"] = None if self.line_weight is None else float(self.line_weight)
        if self.symbol is not UNSET:
            out["symbol"] = self.symbol
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> LineCreate:
        return cls(
            layer_id=data["layerId"],
            a=Vec2.from_json(data["a"]),
            b=Vec2.from_json(data["b"]),
            attrs=UNSET if "attrs" not in data else None if data["attrs"] is None else dict(data["attrs"]),
            color=data.get("color", UNSET),
            expected_revision=data.get("expectedRevision", UNSET),
            label=data.get("label", UNSET),
            line_weight=UNSET if "lineWeight" not in data else None if data["lineWeight"] is None else float(data["lineWeight"]),
            symbol=data.get("symbol", UNSET),
        )


